 p=root/'.dip/config.json'; data=json.loads(p.read_text()); data['verification']['deepseek-editor-harness']={'command':['node','.dip/tools/verify-deepseek-harness.mjs'],'timeoutMs':480000};p.write_text(json.dumps(data,indent=2)+'\n')
 p=root/'.dip/tools/verify-deepseek-harness.mjs';p.parent.mkdir(parents=True,exist_ok=True);p.write_text(wrapper)
